import React, {
  MouseEventHandler,
  ReactNode,
  forwardRef,
  useMemo,
} from 'react';
import styled from 'styled-components';

import { _useBaseInputContext } from './hooks/useBaseInputContext.js';
import { Button } from '../../buttons/button/Button.js';
import { SharedInputPropsContext } from '../../core/contexts/SharedInputPropsContext.js';
import { _useAriaLabelingProps } from '../../core/hooks/useAriaLabelingProps.js';
import { _useId } from '../../core/hooks/useId.js';
import { _useSafeForwardProps } from '../../core/hooks/useSafeForwardProps.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { DOMProps } from '../../core/types/dom.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { Tooltip } from '../../overlays/tooltip/Tooltip.js';

//#region Typings
/** Accepted properties for the BaseInput Button */
export interface BaseInputButtonProps
  extends AriaLabelingProps,
    DOMProps,
    StylingProps,
    DataTestId {
  /** Elements to be displayed in the BaseInput Button slot, preferably an icon or a similar visual element */
  children: ReactNode;
  /**
   * If a button is disabled e.g. it cannot be interacted with.
   * By default, it inherits the disabled prop of the BaseInput, but can be overwritten.
   * @defaultValue false
   */
  disabled?: boolean;
  /**
   * If specified, a tooltip is rendered with this text, which describes what the button does.
   * Please also consider translating the text in an internationalized context and use a short text description for the tooltip.
   * The positioning and placing of the according tooltip will be handled by the component.
   */
  tooltipText?: string;
  /** Called when the button is interacted with. */
  onClick?: MouseEventHandler;
}

//#endregion

//#region Styled Components
const StyledButton = styled(Button)({
  borderRadius: 0, // resets the borderRadius that comes from the Button when multiple buttons are used
  button: {
    borderRadius: 0, // resets the borderRadius that comes from the Button when multiple buttons are used
  },
});
//#endregion

/** Component which allows users to trigger actions or events when clicking or when pressing `Enter` or `Space` while the button has focus. */
export const BaseInputButton = /* @__PURE__ */ forwardRef<
  HTMLButtonElement,
  BaseInputButtonProps
>((props, forwardedRef) => {
  const {
    children,
    tooltipText,
    disabled: propDisabled,
    id,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    ...remainingProps
  }: BaseInputButtonProps = props;

  const { hasError = false, disabled, variant } = _useBaseInputContext();
  const tooltipGeneratedId = _useId({ prefix: 'tooltip' });
  const tooltipId = tooltipText ? id ?? tooltipGeneratedId : undefined;

  const { 'aria-labelledby': ariaLabelledByProp, ...remainingAriaProps } =
    _useAriaLabelingProps(remainingProps);

  const forwardProps = _useSafeForwardProps(remainingProps, {
    ariaLabelledByProp,
    ...remainingAriaProps,
  });

  const ariaLabelledBy = useMemo(
    () =>
      tooltipId || ariaLabelledByProp
        ? `${tooltipId ? tooltipId + ' ' : ''}${ariaLabelledByProp ?? ''}`
        : undefined,
    [ariaLabelledByProp, tooltipId],
  );

  const button = useMemo(
    () => (
      <SharedInputPropsContext.Provider value={{}}>
        <StyledButton
          ref={forwardedRef}
          {...forwardProps}
          variant={variant}
          disabled={propDisabled ?? disabled}
          color={hasError && !disabled ? 'critical' : 'neutral'}
          aria-labelledby={ariaLabelledBy}
          className={consumerClassName}
          style={consumerStyle}
          data-testid={dataTestId}
          {...remainingAriaProps}
        >
          <StyledButton.Prefix>{children}</StyledButton.Prefix>
        </StyledButton>
      </SharedInputPropsContext.Provider>
    ),
    [
      ariaLabelledBy,
      children,
      consumerClassName,
      consumerStyle,
      dataTestId,
      disabled,
      forwardProps,
      forwardedRef,
      hasError,
      propDisabled,
      remainingAriaProps,
      variant,
    ],
  );

  return tooltipText ? (
    <Tooltip id={tooltipId} text={tooltipText} placement="top-end">
      {button}
    </Tooltip>
  ) : (
    button
  );
});

(
  BaseInputButton as typeof BaseInputButton & { displayName: string }
).displayName = 'BaseInput.Button';
